    {view==='goals'&&<><div className="page-heading"><div><span className="eyebrow">{tx("THE BIG PICTURE")}</span><h1>{tx("Long-term goals")}</h1><p>{tx("Define your ambitions and track measurable outcomes.")}</p></div><button className="btn btn-primary" onClick={()=>setModal({kind:'goal'})}><Plus size={16}/> {tx("New goal")}</button></div><div className="page-tabs">{['all','active','planned','paused','completed'].map(f=><button className={goalFilter===f?'selected':''} onClick={()=>setGoalFilter(f)} key={f}>{tx(f==='all'?'All':titleCase(f))} {f==='all'?data.goals.length:data.goals.filter(g=>g.status===f).length}</button>)}</div><div className="goal-cards">{visibleGoals.map(g=>{const projects=data.projects.filter(p=>p.goalId===g.id);return <article key={g.id} className="goal-card"><div className="goal-card-top"><span className={`goal-symbol large ${g.color}`}><Target size={21}/></span><Badge tone={pillClass(g.status)}>{tx(titleCase(g.status))}</Badge></div><h2>{g.title}</h2><p className="goal-description">{g.description||tx('No description added yet.')}</p><div className="goal-card-meta"><span><Flag size={14}/> {tx(g.area)}</span><span><CalendarDays size={14}/> <DateLabel value={g.deadline}/></span></div><div className="goal-card-metric"><span>{g.metric}</span><strong>{g.current} <span>/ {g.target} {g.unit}</span></strong></div><Pbar value={goalProgress(g)}/><div className="goal-card-footer"><span>{projects.length} {tx("projects linked")}</span><button className="link-button" onClick={()=>setModal({kind:'goal',id:g.id})}>{tx("Update goal")} <ArrowRight size={15}/></button></div></article>})}</div>{!visibleGoals.length&&<Empty icon={Target} title={tx("No matching goals")} text={tx("Start with an outcome you care about, then work backwards.")} action={<button className="btn btn-primary" onClick={()=>setModal({kind:'goal'})}><Plus size={15}/> {tx("Create goal")}</button>}/>}</>}
